<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use PDO;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driven\SessionsAdapter;
use Civi\Lughauth\Features\OAuth\Session\Infrastructure\Driven\SessionStoreSqlAdapter;
use Civi\Lughauth\Shared\AppConfig;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Security\AcrValues;

final class SessionStoreSqlAdapterTest extends TestCase
{
    private const string ISSUER = 'https://issuer.example/tenant-sso-race';
    private const string OPENER = 'opener-client';
    private const int CONTENDERS = 8;
    private const int ROUNDS = 5;

    /** Each contender is a separate PHP process with its own connection, released at the same instant. */
    private const string CONTENDER = <<<'PHP'
        <?php
        [, $autoload, $session, $issuer, $clientId, $startAt] = $argv;
        require $autoload;
        try {
            $config = new Civi\Lughauth\Shared\AppConfig();
            $pdo = new PDO($config->get('database.url'), $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
            $store = new Civi\Lughauth\Features\OAuth\Session\Infrastructure\Driven\SessionStoreSqlAdapter($pdo, \Civi\Lughauth\Shared\Security\AcrValues::defaults());
            time_sleep_until((float) $startAt);
            $store->addSessionClient($session, $issuer, $clientId);
            echo 'joined';
        } catch (Throwable $error) {
            echo 'error: ', $error->getMessage();
        }
        PHP;

    /** @var string[] */
    private array $sessions = [];

    protected function tearDown(): void
    {
        if ($this->sessions === []) {
            return;
        }
        $delete = $this->connect()->prepare('DELETE FROM _oauth_session WHERE session = :session');
        foreach ($this->sessions as $session) {
            $delete->execute(['session' => $session]);
        }
    }

    public function testConcurrentSsoJoinsAreAllRecorded(): void
    {
        $store = new SessionStoreSqlAdapter($this->connect(), AcrValues::defaults());
        for ($round = 0; $round < self::ROUNDS; $round++) {
            $session = $this->openSession($store);
            $clients = array_map(static fn (int $i): string => 'rp-' . $i, range(1, self::CONTENDERS));

            $this->assertSame(array_fill(0, self::CONTENDERS, 'joined'), $this->race($session, $clients), 'round ' . $round);

            $joined = $store->loadSession($session)?->ssoClients ?? [];
            sort($joined);
            sort($clients);
            $this->assertSame($clients, $joined, 'round ' . $round);
        }
    }

    public function testConcurrentJoinsOfTheSameClientRecordItOnce(): void
    {
        $store = new SessionStoreSqlAdapter($this->connect(), AcrValues::defaults());
        $session = $this->openSession($store);

        $this->race($session, array_fill(0, self::CONTENDERS, 'rp-same'));
        $store->addSessionClient($session, self::ISSUER, self::OPENER);

        $this->assertSame(['rp-same'], $store->loadSession($session)?->ssoClients);
    }

    public function testJoinIsIgnoredForAnotherIssuer(): void
    {
        $store = new SessionStoreSqlAdapter($this->connect(), AcrValues::defaults());
        $session = $this->openSession($store);

        $store->addSessionClient($session, 'https://issuer.example/other-tenant', 'rp-foreign');

        $this->assertSame([], $store->loadSession($session)?->ssoClients);
    }

    public function testSessionIsPublishedOnlyThroughARandomSid(): void
    {
        $store = new SessionStoreSqlAdapter($this->connect(), AcrValues::defaults());
        $before = time();
        $session = $this->openSession($store, ['pwd', 'mfa'], 'tenant-uid');

        $info = $store->loadSession($session);
        $this->assertNotNull($info);
        $this->assertMatchesRegularExpression('/^[0-9a-f]{32}$/', $info->publicSid);
        $this->assertStringNotContainsString($session, $info->publicSid);
        $this->assertSame(['pwd', 'mfa'], $info->amr);
        $this->assertSame('tenant-uid', $info->tenantId);
        $this->assertSame('urn:lugh:acr:mfa', $info->acr, 'derived from the amr recorded');
        $this->assertGreaterThanOrEqual($before, $info->authTime?->getTimestamp());

        $this->assertSame('csid-' . $session, $store->findActiveSessionBySid($info->publicSid, self::ISSUER)?->csid);
        $this->assertNull($store->findActiveSessionBySid($info->publicSid, 'https://issuer.example/other-tenant'));
        $this->assertNull($store->findActiveSessionBySid($session, self::ISSUER), 'the cookie value is not a sid');

        $store->deleteSessionBySid($info->publicSid);
        $this->assertNull($store->loadSession($session));
    }

    public function testRenewedAuthenticationMovesAuthTimeOnlyForItsIssuer(): void
    {
        $pdo = $this->connect();
        $store = new SessionStoreSqlAdapter($pdo, \Civi\Lughauth\Shared\Security\AcrValues::defaults());
        $session = $this->openSession($store, ['pwd']);
        $pdo->prepare('UPDATE _oauth_session SET auth_time = :old WHERE session = :session')
            ->execute(['old' => (new \DateTimeImmutable('-2 hours'))->format('Y-m-d H:i:s'), 'session' => $session]);

        $store->renewAuthentication($session, 'https://issuer.example/other-tenant', ['mfa']);
        $this->assertLessThan(time() - 3600, $store->loadSession($session)?->authTime?->getTimestamp());

        $store->renewAuthentication($session, self::ISSUER);
        $this->assertEqualsWithDelta(time(), $store->loadSession($session)?->authTime?->getTimestamp(), 5);
        $this->assertSame(['pwd'], $store->loadSession($session)?->amr, 'no methods keep the current ones');

        $store->renewAuthentication($session, self::ISSUER, ['pwd', 'mfa']);
        $this->assertSame(['pwd', 'mfa'], $store->loadSession($session)?->amr);
    }

    public function testSessionWithoutEvidenceHasNoAmr(): void
    {
        $store = new SessionStoreSqlAdapter($this->connect(), AcrValues::defaults());

        $this->assertSame([], $store->loadSession($this->openSession($store))?->amr);
    }

    public function testProfileApiListsAndRevokesByPublicSidOnlyForTheOwner(): void
    {
        $pdo = $this->connect();
        $store = new SessionStoreSqlAdapter($pdo, \Civi\Lughauth\Shared\Security\AcrValues::defaults());
        $profile = new SessionsAdapter($pdo);
        $session = $this->openSession($store);
        $info = $store->loadSession($session);
        $this->assertNotNull($info);

        $listed = $profile->listByUser($info->userId);
        $this->assertSame([$info->publicSid], array_map(static fn ($s): string => $s->sid, $listed), 'never the cookie value');

        $profile->revoke('another-user', $info->publicSid);
        $this->assertNotNull($store->loadSession($session), "another user's sid revokes nothing");
        $profile->revoke($info->userId, $session);
        $this->assertNotNull($store->loadSession($session), 'the cookie value is not a sid');

        $profile->revoke($info->userId, $info->publicSid);
        $this->assertNull($store->loadSession($session));
    }

    /** @param string[] $amr */
    private function openSession(SessionStoreSqlAdapter $store, array $amr = [], ?string $tenantId = null): string
    {
        $session = $this->sessions[] = Uuid::uuid4()->toString();
        $store->saveSession(
            $session,
            new ClientData(self::OPENER, ['authorization_code'], true),
            self::ISSUER,
            new ChallengesState(),
            new AuthenticationResult(valid: true, id: Uuid::uuid4()->toString(), tenant: $tenantId),
            'csid-' . $session,
            new \DateInterval('PT1H'),
            $amr
        );
        return $session;
    }

    /**
     * @param string[] $clients one contender per client
     * @return string[] outcome of every contender: "joined" or "error: ..."
     */
    private function race(string $session, array $clients): array
    {
        $autoload = dirname(__DIR__, 4) . '/vendor/autoload.php';
        // Leave time for every process to boot and connect before the shared start instant.
        $startAt = sprintf('%.6F', microtime(true) + 1.5);
        $processes = [];
        foreach ($clients as $clientId) {
            $process = proc_open(
                [PHP_BINARY, '--', $autoload, $session, self::ISSUER, $clientId, $startAt],
                [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
                $pipes
            );
            self::assertIsResource($process);
            fwrite($pipes[0], self::CONTENDER);
            fclose($pipes[0]);
            $processes[] = [$process, $pipes];
        }

        $outcomes = [];
        foreach ($processes as [$process, $pipes]) {
            $outcomes[] = trim((string) stream_get_contents($pipes[1])) ?: trim((string) stream_get_contents($pipes[2]));
            fclose($pipes[1]);
            fclose($pipes[2]);
            proc_close($process);
        }
        return $outcomes;
    }

    private function connect(): PDO
    {
        $config = new AppConfig();
        $dsn = $config->get('database.url');
        if (!is_string($dsn) || !str_starts_with($dsn, 'mysql:')) {
            $this->markTestSkipped('MySQL integration database not configured');
        }

        try {
            $pdo = new PDO($dsn, $config->get('database.username'), $config->get('database.password'), [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            ]);
        } catch (\PDOException) {
            $this->markTestSkipped('MySQL integration database not available');
        }
        if ($pdo->query("SHOW COLUMNS FROM _oauth_session LIKE 'sid'")->rowCount() === 0) {
            $this->markTestSkipped('Migration with _oauth_session.sid (20261021120000) not applied');
        }
        return $pdo;
    }
}
